using System.Diagnostics;
using System.Text.Json;
namespace CombatSolver.Engine.Common;
internal static class PileProjectionProbe
{
    private sealed class Counts { public long Calls, Cards, Selected, Ticks, WarmCalls, WarmCards; }
    private sealed class Cell
    {
        public readonly Dictionary<(int,int),Counts> Queries = new();
        public readonly Dictionary<(int,int),Counts> Invalidations = new();
    }
    private static readonly ThreadLocal<Cell> Cells = new(() => new Cell(), true);
    static PileProjectionProbe() => AppDomain.CurrentDomain.ProcessExit += (_, _) => Write();
    internal static void Record(int kind, int cards, int selected, long start, int pile = -1)
    {
        long elapsed = Stopwatch.GetTimestamp()-start;
        var table=Cells.Value!.Queries;var key=(kind,pile);
        if (!table.TryGetValue(key,out var c)) table[key]=c=new Counts();
        c.Calls++; c.Cards+=cards; c.Selected+=selected; c.Ticks+=elapsed;
    }
    internal static void Invalidation(int kind, int pile, int cards, bool warm)
    {
        var table=Cells.Value!.Invalidations;var key=(kind,pile);
        if (!table.TryGetValue(key,out var c)) table[key]=c=new Counts();
        c.Calls++; c.Cards+=cards;
        if(warm) { c.WarmCalls++; c.WarmCards+=cards; }
    }
    private static string PileName(int value) => value<0 ? "root" : ((MegaCrit.Sts2.Core.Entities.Cards.PileType)value).ToString();
    private static void Write()
    {
        string? path=Environment.GetEnvironmentVariable("PILE_PROJECTION_PROBE_OUTPUT"); if(path is null)return;
        string[] queries=["opaque-pile","filter-refusal","reused-indices","wrapper-alias","cold-indices","root-filter-capture","reserved"];
        string[] causes=["pile-shape","writable-preview","card-caches","ownership-change","structure-completion","opaque-disable"];
        var qr=Cells.Values.SelectMany(c=>c.Queries).GroupBy(p=>p.Key).OrderBy(g=>g.Key.Item1).ThenBy(g=>g.Key.Item2).Select(g=>new {kind=queries[g.Key.Item1],pile=PileName(g.Key.Item2),calls=g.Sum(p=>p.Value.Calls),cards=g.Sum(p=>p.Value.Cards),selected=g.Sum(p=>p.Value.Selected),cumulativeMilliseconds=g.Sum(p=>p.Value.Ticks)*1000d/Stopwatch.Frequency}).ToArray();
        var ir=Cells.Values.SelectMany(c=>c.Invalidations).GroupBy(p=>p.Key).OrderBy(g=>g.Key.Item1).ThenBy(g=>g.Key.Item2).Select(g=>new {cause=causes[g.Key.Item1],pile=PileName(g.Key.Item2),calls=g.Sum(p=>p.Value.Calls),cards=g.Sum(p=>p.Value.Cards),warmCalls=g.Sum(p=>p.Value.WarmCalls),warmCards=g.Sum(p=>p.Value.WarmCards)}).ToArray();
        File.WriteAllText(path,JsonSerializer.Serialize(new {diagnosticOnly=true,scope="query time and invalidation categories; warm means a projection existed immediately before invalidation; no cold-query cause attribution",threadCells=Cells.Values.Count,queries=qr,invalidations=ir},new JsonSerializerOptions{WriteIndented=true}));
    }
}

